import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int v, cap, cost, rev;
        Edge(int v, int cap, int cost, int rev) {
            this.v = v;
            this.cap = cap;
            this.cost = cost;
            this.rev = rev;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        final int Z = 100;
        final int N = Z * Z;
        List<List<Edge>> graph = new ArrayList<>();
        for (int i = 0; i <= N + 1; i++) {
            graph.add(new ArrayList<>());
        }

        int s = 0;
        int t = n * 100 + 1;

        // Helper method to add edges
        class GraphHelper {
            void addEdge(int u, int v, int cap, int cost) {
                graph.get(u).add(new Edge(v, cap, cost, graph.get(v).size()));
                graph.get(v).add(new Edge(u, 0, -cost, graph.get(u).size() - 1));
            }
        }
        GraphHelper gh = new GraphHelper();

        for (int i = 1; i <= 100; ++i)
            gh.addEdge(i, t, 100, 0);

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; ++i) {
            int v = Integer.parseInt(st.nextToken());
            gh.addEdge(s, (v - 1) * 100 + 1, 1, 0);
        }

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j < 100; ++j) {
                gh.addEdge((i - 1) * 100 + j, (i - 1) * 100 + j + 1, 100, c);
            }
        }

        for (int i = 0; i < m; ++i) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            for (int j = 1; j < 100; ++j) {
                int idx = (u - 1) * 100 + j;
                int idy = (v - 1) * 100 + j + 1;
                for (int k = 1; k <= 50; ++k) {
                    int costVal = c + (k * k - (k - 1) * (k - 1)) * d;
                    gh.addEdge(idx, idy, 1, costVal);
                }
            }
            for (int j = 1; j < 100; ++j) {
                int idx = (v - 1) * 100 + j;
                int idy = (u - 1) * 100 + j + 1;
                for (int k = 1; k <= 50; ++k) {
                    int costVal = c + (k * k - (k - 1) * (k - 1)) * d;
                    gh.addEdge(idx, idy, 1, costVal);
                }
            }
        }

        int flow = 0, cost = 0;
        int[] dist = new int[N + 2];
        int[] parent = new int[N + 2];
        int[] parentEdge = new int[N + 2];

        while (true) {
            Arrays.fill(dist, Integer.MAX_VALUE);
            dist[s] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int i = 0; i < graph.get(u).size(); ++i) {
                    Edge e = graph.get(u).get(i);
                    if (e.cap > 0 && dist[e.v] > dist[u] + e.cost) {
                        dist[e.v] = dist[u] + e.cost;
                        parent[e.v] = u;
                        parentEdge[e.v] = i;
                        q.offer(e.v);
                    }
                }
            }
            if (dist[t] == Integer.MAX_VALUE) break;
            int f = Integer.MAX_VALUE;
            for (int u = t; u != s; u = parent[u]) {
                f = Math.min(f, graph.get(parent[u]).get(parentEdge[u]).cap);
            }
            for (int u = t; u != s; u = parent[u]) {
                Edge e = graph.get(parent[u]).get(parentEdge[u]);
                e.cap -= f;
                graph.get(u).get(e.rev).cap += f;
            }
            cost += dist[t] * f;
            flow += f;
        }
        System.out.println(cost);
    }
}

